using Arcadia.HallServer;
using Microsoft.AspNetCore.Builder;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Hosting.WindowsServices;

// Standalone entry point.
//
//   pair-server --url https://<ref>.supabase.co/functions/v1/agent-bridge --code XXXX-XXXX-XXXX --name "Cashier PC"
//       one-time: registers this Hall Server with the cloud (code generated by the owner in the dashboard)
//   --Cloud:Mode=Supabase     normal run (uses the stored credential)
//   --Cloud:Mode=Dev          in-memory fake cloud, development only
var config = new ConfigurationBuilder()
    .SetBasePath(AppContext.BaseDirectory) // a Windows service starts in System32
    .AddJsonFile("appsettings.json", optional: true)
    .AddEnvironmentVariables("ARCADIA_")
    .AddCommandLine(args)
    .Build();

var opt = config.GetSection("HallServer").Get<HallServerOptions>() ?? new HallServerOptions();
var protector = new DpapiSecretProtector();
var settingsStore = new CloudSettingsStore(opt.DataDir, protector);

if (args.Length > 0 && args[0] == "info")
{
    // What a technician needs when pairing PCs: the CA fingerprint, the address(es) and the port.
    var ca = LocalCa.LoadOrCreate(Path.Combine(opt.DataDir, "pki"), protector);
    Console.WriteLine($"CA fingerprint : {ca.Fingerprint}");
    Console.WriteLine($"Port           : {opt.Port}");
    Console.WriteLine($"Cloud paired   : {(settingsStore.Load() is null ? "NO (run pair-server)" : "yes")}");
    Console.WriteLine("Server address (use one of these when pairing a PC):");
    Console.WriteLine($"  https://{Environment.MachineName}:{opt.Port}");
    foreach (var ni in NetworkInterface.GetAllNetworkInterfaces().Where(n => n.OperationalStatus == OperationalStatus.Up && n.NetworkInterfaceType != NetworkInterfaceType.Loopback))
        foreach (var a in ni.GetIPProperties().UnicastAddresses.Where(a => a.Address.AddressFamily == AddressFamily.InterNetwork))
            Console.WriteLine($"  https://{a.Address}:{opt.Port}");
    return 0;
}

if (args.Length > 0 && args[0] == "pair-server")
{
    string? Arg(string n) { var i = Array.IndexOf(args, n); return i >= 0 && i + 1 < args.Length ? args[i + 1] : null; }
    var url = Arg("--url"); var code = Arg("--code");
    if (url is null || code is null)
    {
        Console.Error.WriteLine("Usage: pair-server --url <agent-bridge url> --code <code> [--name <label>]");
        return 2;
    }
    try
    {
        using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(30) };
        var hall = await HallServerPairing.PairAsync(http, url, code, Arg("--name") ?? Environment.MachineName, settingsStore);
        Console.WriteLine($"Paired with hall {hall}. The credential is stored protected on this machine.");
        return 0;
    }
    catch (Exception e) when (e is InvalidOperationException or HttpRequestException)
    {
        Console.Error.WriteLine(e.Message);
        return 1;
    }
}

ICloudBridge cloud;
switch (config["Cloud:Mode"])
{
    case "Dev":
        cloud = new DevCloudBridge();
        break;
    case "Supabase":
    {
        var s = settingsStore.Load();
        if (s is null)
        {
            Console.Error.WriteLine("This Hall Server is not paired with the cloud. Run pair-server first.");
            return 2;
        }
        cloud = new SupabaseCloudBridge(new HttpClient { Timeout = TimeSpan.FromSeconds(20) }, s);
        break;
    }
    default:
        Console.Error.WriteLine("Set --Cloud:Mode=Supabase (normal) or --Cloud:Mode=Dev (development only).");
        return 2;
}

var app = HallServerHost.Build(opt, cloud, protector, windowsService: WindowsServiceHelpers.IsWindowsService());
await app.RunAsync();
return 0;
